use relay.feed;

fn publish(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let frames = feed.frames();
    var total = 0;
    var i = 0;
    while i < frames.len() {
        let value = match feed.decode(frame: frames.get(i)) {
            Some(n) => n,
            None => 0,
        };
        total = total + value;
        i = i + 1;
    }
