use galley.menu;
use galley.kitchen;

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let board = galley.menu.board();
    var i = 0;
    while i < board.len() {
        if i > 0 {
            io.write(text: ";")?;
        }
        match board.get(index: i) {
            Some(dish) => galley.kitchen.serve(io: io, dish: dish)?,
            None => unit,
        };
        i = i + 1;
    }
    return Ok(unit);
}

use stable.herd.{lineup, feed};
use stable.ledger.{entry};

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let ponies = lineup();
    var i = 0;
    var out = "";
    while i < ponies.len() {
        let fed = feed(pony: ponies[i], scoops: 3);
        let e = entry(fed);
        if i == 0 {
            out = e;
        } else {
            out = out.concat(other: ",").concat(other: e);
        }
        i = i + 1;
    }
    io.write(text: out)?;
    return Ok(unit);
}

