use depot.locker;

pub fn report() -> String {
    var ax = depot.locker.arrive(label: "ax");
    var bay = depot.locker.arrive(label: "bay");
    var cod = depot.locker.arrive(label: "cod");
    ax = depot.locker.stow(locker: ax, load: 12);
    ax = depot.locker.stow(locker: ax, load: 9);
    bay = depot.locker.stow(locker: bay, load: 30);
    bay = depot.locker.stow(locker: bay, load: 25);
    cod = depot.locker.stow(locker: cod, load: 5);
    [
        depot.locker.tag(locker: ax),
        depot.locker.tag(locker: bay),
        depot.locker.tag(locker: cod),
    ].join(sep: ",")
}

use harbor.signal;

fn render(s: Signal) -> String {
    match s {
        Calm => "calm",
        Gale(speed) => "gale:".concat(other: speed.to_text()),
        Fog(density) => "fog:".concat(other: density),
    }
}

fn entries() -> String {
    let items = signal.day();
    var out = "";
    var i = 0;
    while i < items.len() {
        if i > 0 {
            out = out.concat(other: ";");
        }
        out = out.concat(other: render(items.get(i)));
        i = i + 1;
    }
    out
}

