use mill.stock;
use mill.rules;

fn lines() -> String {
    let planks = stock.inventory();
    var out = "";
    var first = true;
    var i = 0;
    while i < planks.len() {
        let plank = planks.get(i);
        if rules.keep(plank) {
            if first {
                out = rules.label(plank);
                first = false;
            } else {
                out = out.concat(other: ",").concat(other: rules.label(plank));
            }
        }
        i = i + 1;
    }
    out
}

